#include <iostream>
#include <vector>
#include <functional>
#include <algorithm>
using namespace std;

struct Plugin { string name; function<void()> execute; };

class Registry {
    vector<Plugin> plugins;
public:
    void registerPlugin(const string& name, function<void()> fn) {
        plugins.push_back({name, fn});
    }
    void runPlugin(const string& name) {
        auto it = find_if(plugins.begin(), plugins.end(), [&](const Plugin& p) { return p.name == name; });
        if (it != plugins.end()) it->execute();
        else cout << "Plugin not found: " << name << endl;
    }
};

int main() {
    Registry reg;
    reg.registerPlugin("math", []() { cout << "5 + 3 = " << (5+3) << endl; });
    reg.registerPlugin("greet", []() { cout << "Hello from plugin!" << endl; });
    reg.runPlugin("math");
    reg.runPlugin("greet");
    reg.runPlugin("unknown");
    return 0;
}
